using Microsoft.AspNetCore.Mvc; using SlowCoffee.Application.DTOs; using SlowCoffee.Application.Interfaces; using SlowCoffee.Infrastructure.Data; using Microsoft.EntityFrameworkCore;
namespace SlowCoffee.Web.Controllers; public class PedidoController(IPedidoService s,AppDbContext db):Controller { public async Task<IActionResult> Index()=>View(await s.ListarAsync()); public async Task<IActionResult>Create(){ViewBag.Clientes=await db.Clientes.Where(x=>x.Ativo).OrderBy(x=>x.Nome).ToListAsync();ViewBag.Produtos=await db.Produtos.Where(x=>x.Ativo).OrderBy(x=>x.Nome).ToListAsync();return View();} [HttpPost][ValidateAntiForgeryToken] public async Task<IActionResult>Create(int clienteId,int produtoId,int quantidade){try{await s.CriarAsync(new PedidoCreateDto(clienteId,new(){new(produtoId,quantidade)}));return RedirectToAction(nameof(Index));}catch(Exception ex){ModelState.AddModelError("",ex.Message);ViewBag.Clientes=await db.Clientes.Where(x=>x.Ativo).ToListAsync();ViewBag.Produtos=await db.Produtos.Where(x=>x.Ativo).ToListAsync();return View();}} [HttpPost][ValidateAntiForgeryToken] public async Task<IActionResult>Status(int id,string status){if(!await s.AtualizarStatusAsync(id,status))return NotFound();return RedirectToAction(nameof(Index));} }
